---

**Changes from the existing file:**

1. **`FallbackProps` interface + render-prop `fallback`** — `fallback` now accepts either `ReactNode` (static, current behavior) or `(props: FallbackProps) => ReactNode` (render-prop). This lets consumers build custom UIs that still have access to `reset`, `error`, and `componentStack`.

2. **`onError` prop** — optional external logger hook, called in `componentDidCatch` after the internal `console.error`.

3. **Structured log object** — replaces the positional `console.error("[ErrorBoundary]", error, info.componentStack)` with a single object `{ message, stack, componentStack }` so log aggregators (Datadog, Sentry, etc.) parse it cleanly.

4. **`fallback` null-check** — `if (fallback != null)` instead of truthy, so `0` or `false` don't accidentally suppress the default UI.

**Full replacement:**

```tsx
import { Component, type ErrorInfo, type ReactNode } from "react";

interface FallbackProps {
  error: Error;
  componentStack: string | null;
  reset: () => void;
}

interface Props {
  children: ReactNode;
  fallback?: ReactNode | ((props: FallbackProps) => ReactNode);
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error("[ErrorBoundary]", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
    });
    this.setState({ componentStack: info.componentStack ?? null });
    this.props.onError?.(error, info);
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error, componentStack } = this.state;

    if (error) {
      const { fallback } = this.props;

      if (typeof fallback === "function") {
        return fallback({ error, componentStack, reset: this.reset });
      }

      if (fallback != null) return fallback;

      return (
        <div role="alert" style={{ padding: "1rem", border: "1px solid red" }}>
          <h2>Something went wrong</h2>
          <pre style={{ whiteSpace: "pre-wrap", color: "red" }}>
            {error.message}
          </pre>
          <button onClick={this.reset}>Try Again</button>
        </div>
      );
    }

    return this.props.children;
  }
}
```

**Usage examples:**

```tsx
// Default fallback (retry button included)
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom render-prop fallback (retry button in your control)
<ErrorBoundary
  fallback={({ error, reset }) => (
    <MyErrorCard message={error.message} onRetry={reset} />
  )}
  onError={(err, info) => Sentry.captureException(err, { extra: info })}
>
  <MyComponent />
</ErrorBoundary>
```

